def encontrar_maior(arr):
    maior = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > maior:
            maior = arr[i]
    return maior

print(encontrar_maior([14, 3, 42, 19, 42, 8]))

def eh_par(numero):
    if numero % 2 == 0:
        return True
    else:
        return False

print(eh_par(7))
